package scp_candidate.EIT_Acquisition_Session_Coordinator

import org.sireum._
import art._
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun

@sig trait AcquisitionCommandPolicy_Api {
  def id: Art.BridgeId
  def monitoringDecision_Id : Art.PortId
  def acquisitionCommand_Id : Art.PortId

  // Logika spec var representing port state for outgoing data port
  @spec var acquisitionCommand: EIT_Acquisition_Session_Coordinator.AcquisitionCommand.Type = $

  def put_acquisitionCommand(value : EIT_Acquisition_Session_Coordinator.AcquisitionCommand.Type) : Unit = {
    Contract(
      Modifies(acquisitionCommand),
      Ensures(
        acquisitionCommand == value
      )
    )
    Spec {
      acquisitionCommand = value
    }

    Art.putValue(acquisitionCommand_Id, EIT_Acquisition_Session_Coordinator.AcquisitionCommand_Payload(value))
  }

  def logInfo(msg: String): Unit = {
    Art.logInfo(id, msg)
  }

  def logDebug(msg: String): Unit = {
    Art.logDebug(id, msg)
  }

  def logError(msg: String): Unit = {
    Art.logError(id, msg)
  }
}

@datatype class AcquisitionCommandPolicy_Initialization_Api (
  val id: Art.BridgeId,
  val monitoringDecision_Id : Art.PortId,
  val acquisitionCommand_Id : Art.PortId) extends AcquisitionCommandPolicy_Api

@datatype class AcquisitionCommandPolicy_Operational_Api (
  val id: Art.BridgeId,
  val monitoringDecision_Id : Art.PortId,
  val acquisitionCommand_Id : Art.PortId) extends AcquisitionCommandPolicy_Api {

  // Logika spec var representing port state for incoming data port
  @spec var monitoringDecision: EIT_Acquisition_Session_Coordinator.MonitoringDecisionSnapshot = $

  def get_monitoringDecision() : Option[EIT_Acquisition_Session_Coordinator.MonitoringDecisionSnapshot] = {
    Contract(
      Ensures(
        Res == Some(monitoringDecision)
      )
    )
    val value : Option[EIT_Acquisition_Session_Coordinator.MonitoringDecisionSnapshot] = Art.getValue(monitoringDecision_Id) match {
      case Some(EIT_Acquisition_Session_Coordinator.MonitoringDecisionSnapshot_Payload(v)) => Some(v)
      case Some(v) =>
        Art.logError(id, s"Unexpected payload on port monitoringDecision.  Expecting 'EIT_Acquisition_Session_Coordinator.MonitoringDecisionSnapshot_Payload' but received ${v}")
        None[EIT_Acquisition_Session_Coordinator.MonitoringDecisionSnapshot]()
      case _ => None[EIT_Acquisition_Session_Coordinator.MonitoringDecisionSnapshot]()
    }
    return value
  }
}
